// The team inspector (#2193; read-only #2382) — the right panel, in one of two modes.
// POSITION: who this node IS (the persona it embodies, presented) · the CAPABILITY FLOOR of the role
// that persona runs under · the auto-derived communication surface.
// RELATIONSHIP: the edge's archetype and the communication forms flowing each way.
//
// IT PRESENTS; IT DOES NOT EDIT. The persona picker, the inlined <PersonaEditor>, the label field, the
// archetype picker and the two ConfirmButton deletes were interim manual overrides (#2383/#2384) on the
// way to the read-only goal (#2382) — they are gone. Teams, positions, personas and relationships are
// authored by the team architect through `bsc teams` / `bsc persona`; this panel is where you read the
// result. Nothing here holds state: every value is derived from the store on render, so the panel can
// never show a stale edit-in-progress that the architect has since overwritten.
//
// The CAPABILITY block reads the persona's OWN floor. It used to look the capability up by role
// (`roleCapability(persona.role)`), which was right while the role table was the source — and became
// wrong the moment a persona could carry a floor NARROWER than its role's. A panel that showed the
// role's row would have told you a session may write code while the session it describes cannot.
//
// It mirrors `paneCapability` in the launch path deliberately, fallback included: floor if present,
// else the role's row. What this panel shows and what the session gets are then the same computation,
// so they cannot drift into disagreeing about an agent's permissions.
import { Stack } from "@/shared/ui/layout/Stack";
import { Row } from "@/shared/ui/layout/Row";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import { Chip, type ChipTone } from "@/shared/ui/data/Chip";
import { Code } from "@/shared/ui/data/Code";
import { ColorSwatch } from "@/shared/ui/controls/ColorSwatch";
import { IconBox } from "@/shared/ui/data/IconBox";
import { SectionLabel, type SectionLabelProps } from "@/shared/ui/layout/SectionLabel";
import { roleCapability, roleDeniedCommands, type AccessTier, type RoleCapability } from "@/shared/lib/session/sessionRoles";
import type { Persona } from "@/features/personas";
import { archetypeById, formById, type Team } from "@/features/teams/lib/team";
import { positionDisplay, positionComms, hueColor } from "@/features/teams/lib/orgView";
import { FormChip, FormLane } from "@/features/teams/components";
import type { Selection } from "@/features/teams/TeamsCanvas";

/** The inspector's block header — the shared SectionLabel (`right` slot, #2420) at the team
 *  designer's `.ulabel` size, with the block's standard 9px bottom gap baked in. */
function BlockLabel(props: Omit<SectionLabelProps, "size" | "style">) {
  return <SectionLabel size={9.5} style={{ marginBottom: 9 }} {...props} />;
}

interface InspectorProps {
  org: Team;
  /** Every team — to count how many positions share a persona (the "used in N" note). */
  orgs: Team[];
  personas: Persona[];
  sel: Selection;
  onSelectNode: (nodeId: string) => void;
}

// Fills its (drag-resizable) wrapper column in GraphCanvas — the width is owned by the layout, not here.
const PANEL: React.CSSProperties = { flex: 1, minWidth: 0, borderLeft: "1px solid var(--border-soft)", overflowY: "auto" };
const BLOCK: React.CSSProperties = { padding: "15px 17px", borderBottom: "1px solid var(--border-soft)" };

/** Access-tier → chip tone, matching the role gate's own legend: `write` is the widest grant (accent),
 *  `read` is bounded (info), `none` is the floor (neutral). */
function tierTone(tier: AccessTier): ChipTone {
  return tier === "write" ? "accent" : tier === "read" ? "info" : "neutral";
}

/** The five capability axes, in the order the role gate reasons about them (#219). */
const AXES: ("git" | "github" | "code" | "net" | "ui")[] = ["git", "github", "code", "net", "ui"];

/** The footer every mode carries: this panel reads, and here is what writes. Naming the two commands
 *  is the whole point of removing the controls — the capability did not disappear, it moved to the
 *  surface that owns it, and a user who came looking for a delete button needs to be told where it went. */
function AuthoredElsewhere() {
  return (
    <Box style={{ padding: "13px 17px 22px" }}>
      <Text as="div" size={10.5} tone="dim" style={{ lineHeight: 1.5 }}>
        Read-only. Teams, positions and personas are authored by the team architect —{" "}
        <Text as="span" mono size={10}>bsc teams</Text> · <Text as="span" mono size={10}>bsc persona</Text>.
      </Text>
    </Box>
  );
}

/** The capability a persona actually launches under: its own floor when it has one, else its role's
 *  row. The SAME resolution `paneCapability` performs at launch — see the file header for why that
 *  matters more than it looks. */
function personaCapability(persona: Persona): RoleCapability {
  // Converted FIELD BY FIELD, with no cast — see the twin in `sessionLaunch`. `writeGlobs` is required
  // here and optional on a floor, and a cast asserting the required shape without supplying it is what
  // hid the missing field in the first place.
  const f = persona.floor;
  return f
    ? {
        role: persona.role,
        github: f.github, git: f.git, code: f.code, net: f.net, ui: f.ui,
        writeGlobs: f.writeGlobs ?? [],
        harvestRoots: f.harvestRoots,
        allow: f.allow,
      }
    : roleCapability(persona.role);
}

/** Each axis where `persona` grants LESS than the persona it derives from, as `was → now`. Empty when
 *  it derives from nothing, when the ancestor is missing, or when nothing was tightened. */
function narrowedAxes(persona: Persona, personas: Persona[]): { axis: string; was: string; now: string }[] {
  const parent = persona.derivesFrom ? personas.find((p) => p.id === persona.derivesFrom) : undefined;
  if (!parent?.floor || !persona.floor) return [];
  const rank: Record<string, number> = { none: 0, read: 1, write: 2 };
  return AXES.flatMap((axis) => {
    const was = parent.floor![axis], now = persona.floor![axis];
    return (rank[now] ?? 0) < (rank[was] ?? 0) ? [{ axis, was, now }] : [];
  });
}

/**
 * The permission floor behind an agent position: the access tiers, the paths it may write, the confined
 * command surface, and the commands the gate denies it.
 *
 * A DERIVED persona also shows what it gave up. Showing only the resulting tiers hides the single most
 * interesting fact about such a persona — that someone deliberately tightened it — and makes it
 * indistinguishable from a persona that was simply authored narrow. The whole point of `derivesFrom` is
 * that the narrowing is a relationship, so the panel renders the relationship rather than its result.
 */
function CapabilityBlock({ persona, personas }: { persona: Persona; personas: Persona[] }) {
  const cap = personaCapability(persona);
  const denied = roleDeniedCommands(cap);
  const scope = cap.writeGlobs.length > 0 ? cap.writeGlobs.join("  ") : "\u2014";
  const narrowed = narrowedAxes(persona, personas);
  const parentName = persona.derivesFrom
    ? personas.find((p) => p.id === persona.derivesFrom)?.name ?? persona.derivesFrom
    : undefined;

  return (
    <Box style={BLOCK}>
      <BlockLabel
        right={<Text as="span" mono size={9} tone="dim">
          {parentName ? `derives from \u00b7 ${parentName}` : `role \u00b7 ${persona.role}`}
        </Text>}
      >
        Capability
      </BlockLabel>

      {/* The access tiers — the least-privilege floor this session launches under. */}
      <Row gap={6} wrap>
        {AXES.map((axis) => (
          <Chip key={axis} tone={tierTone(cap[axis])}>{`${axis} \u00b7 ${cap[axis]}`}</Chip>
        ))}
      </Row>

      {/* What this persona gave up relative to its ancestor. Absent for a persona that derives from
          nothing, which is most of them. */}
      {narrowed.length > 0 && (
        <Row gap={5} wrap align="baseline" style={{ marginTop: 8 }}>
          <Text as="span" size={10} tone="dim">narrowed</Text>
          {narrowed.map((n) => (
            <Chip key={n.axis} tone="info">{`${n.axis} \u00b7 ${n.was} \u2192 ${n.now}`}</Chip>
          ))}
        </Row>
      )}

      {/* Write-scope: the globs this persona may write. An em-dash means no file writes at all. */}
      <Row gap={7} align="baseline" wrap style={{ marginTop: 10 }}>
        <Text as="span" size={10} tone="dim">write-scope</Text>
        <Text as="span" mono size={10.5} tone={cap.writeGlobs.length > 0 ? "muted" : "dim"}>{scope}</Text>
      </Row>

      {/* The CONFINED surface, when there is one. Its presence is what makes a persona confined at all,
          so an absent list is not "no commands" — it is the broad baseline, which is the wider case and
          therefore the one worth not implying. */}
      {(cap.allow?.length ?? 0) > 0 && (
        <Box style={{ marginTop: 10 }}>
          <Text as="div" size={10} tone="dim" style={{ marginBottom: 5 }}>
            confined to {cap.allow!.length} command{cap.allow!.length === 1 ? "" : "s"}
          </Text>
          <Row gap={5} wrap>
            {cap.allow!.map((cmd) => <Chip key={cmd} tone="accent">{cmd}</Chip>)}
          </Row>
        </Box>
      )}

      {/* The mutating commands the gate denies (deny beats allow at launch). */}
      {denied.length > 0 && (
        <Box as="details" style={{ marginTop: 10 }}>
          <Box as="summary" className="mono" style={{ cursor: "pointer", fontSize: 10, color: "var(--fg-dim)", userSelect: "none" }}>
            {denied.length} denied command{denied.length === 1 ? "" : "s"}
          </Box>
          <Row gap={5} wrap style={{ marginTop: 8 }}>
            {denied.map((cmd) => <Chip key={cmd} tone="danger">{cmd}</Chip>)}
          </Row>
        </Box>
      )}
    </Box>
  );
}

/** The persona a position embodies, presented. Everything the removed <PersonaEditor> let you TYPE is
 *  here as text: the charter it is accountable for, the model it launches on, the skills written into
 *  its session, and the start prompt injected at launch. */
function PersonaBlock({ persona, uses, headerName }: { persona: Persona; uses: number; headerName: string }) {
  const resp = persona.responsibilities ?? [];
  // The panel header already names the POSITION, which is the persona's name unless the position
  // carries a local label override. Repeating an identical string immediately below it is noise, so
  // the identity's own name is shown only when it actually differs from what the header said.
  const nameAddsInfo = persona.name !== headerName;

  return (
    <Box style={BLOCK}>
      <BlockLabel right={uses > 1 ? <Text as="span" mono size={9} tone="dim">shared · used in {uses}</Text> : undefined}>Persona</BlockLabel>

      {(nameAddsInfo || persona.pooled) && (
        <Row gap={8} align="baseline" wrap>
          {nameAddsInfo && <Text as="span" weight={600} size={13}>{persona.name}</Text>}
          {persona.pooled && <Chip tone="info">pooled</Chip>}
        </Row>
      )}
      {persona.blurb && (
        <Text as="p" size={11} tone="muted" style={{ lineHeight: 1.45, margin: nameAddsInfo || persona.pooled ? "6px 0 0" : 0 }}>{persona.blurb}</Text>
      )}

      {/* charter — what this identity is accountable for (#2193) */}
      {resp.length > 0 && (
        <Box style={{ marginTop: 12 }}>
          <SectionLabel size={9.5} style={{ marginBottom: 6 }}>responsibilities · {resp.length}</SectionLabel>
          <Stack gap={4}>
            {resp.map((r, i) => (
              <Row key={i} gap={6} align="baseline">
                <Text as="span" tone="dim" size={10}>·</Text>
                <Text as="span" size={11.5} tone="muted" style={{ lineHeight: 1.4 }}>{r}</Text>
              </Row>
            ))}
          </Stack>
        </Box>
      )}

      <Row gap={7} align="baseline" style={{ marginTop: 12 }}>
        <Text as="span" size={10} tone="dim">model</Text>
        <Text as="span" mono size={10.5} tone={persona.model ? "accent" : "dim"}>{persona.model || "session default"}</Text>
      </Row>

      <Box style={{ marginTop: 10 }}>
        <SectionLabel size={9.5} style={{ marginBottom: 6 }}>attached skills · {persona.skills.length}</SectionLabel>
        {persona.skills.length === 0 ? (
          <Text as="div" mono size={10} tone="dim">none attached</Text>
        ) : (
          <Row gap={5} wrap>
            {persona.skills.map((id) => <Chip key={id}>{id}</Chip>)}
          </Row>
        )}
      </Box>

      {/* The prose injected at launch — collapsed, because the worker/director personas carry their
          whole protocol here and it would otherwise bury every block below it. */}
      <Box as="details" style={{ marginTop: 12 }}>
        <Box as="summary" className="mono" style={{ cursor: "pointer", fontSize: 10, color: "var(--fg-dim)", userSelect: "none" }}>
          Start prompt
        </Box>
        {persona.startPrompt ? (
          <Code style={{ marginTop: 6 }}>{persona.startPrompt}</Code>
        ) : (
          <Text as="div" mono size={9.5} tone="dim" style={{ marginTop: 6, lineHeight: 1.5 }}>
            No start prompt — falls back to the {persona.role} role's own kickoff assembly at launch.
          </Text>
        )}
      </Box>
    </Box>
  );
}

export function TeamsInspector({ org, orgs, personas, sel, onSelectNode }: InspectorProps) {
  if (sel.type === "node") {
    const pos = org.positions.find((p) => p.nodeId === sel.id);
    if (!pos) return <Box style={PANEL} />;
    const d = positionDisplay(pos, personas);
    const persona = pos.personaId ? personas.find((p) => p.id === pos.personaId) : undefined;
    const comms = positionComms(org, pos, personas);
    // How many positions across every team embody this same persona — the identity is shared, so the
    // count is what tells you this block describes more than the node you clicked.
    const uses = persona ? orgs.reduce((n, o) => n + o.positions.filter((p) => p.personaId === persona.id).length, 0) : 0;

    return (
      <Box style={PANEL}>
        {/* header */}
        <Box style={{ ...BLOCK, padding: "16px 17px 14px" }}>
          <Row gap={11} align="center">
            <IconBox size={40} radius={11} fontSize={18} color="#fff" background="var(--accent)">{d.glyph}</IconBox>
            <Box style={{ flex: 1, minWidth: 0 }}>
              <Text as="div" weight={600} size={16}>{d.name}</Text>
              <Row gap={7} align="center" style={{ marginTop: 3 }}>
                <Text as="span" size={10} tone="muted">{d.dept}</Text>
                {d.role && <Chip color="var(--accent)">{d.role}</Chip>}
              </Row>
            </Box>
          </Row>
          {/* A resource/external node has no identity block — the header's dept row already names its
              kind, so the only thing left to say is what that kind MEANS. An agent gets this from its
              persona blurb instead, one block down. */}
          {pos.kind !== "agent" && d.blurb && (
            <Text as="p" size={11} tone="muted" style={{ lineHeight: 1.45, margin: "10px 0 0" }}>{d.blurb}</Text>
          )}
        </Box>

        {/* identity — a persona (agent) or a name (resource/external) */}
        {pos.kind === "agent" ? (
          persona ? (
            <PersonaBlock persona={persona} uses={uses} headerName={d.name} />
          ) : (
            <Box style={BLOCK}>
              <BlockLabel>Persona</BlockLabel>
              <Text as="div" size={11} tone="dim" style={{ lineHeight: 1.45 }}>
                No persona bound — this position has no identity yet.
              </Text>
            </Box>
          )
        ) : null}

        {/* the permission floor behind the identity — agents only (a resource/external runs nothing) */}
        {pos.kind === "agent" && persona && <CapabilityBlock persona={persona} personas={personas} />}

        {/* communication (derived) */}
        <Box style={{ padding: "15px 17px 20px" }}>
          <BlockLabel right={<Text as="span" mono size={9} tone="dim">auto · from relationships</Text>}>Communication</BlockLabel>
          {comms.length === 0 ? (
            <Text as="div" size={11} tone="dim">No relationships — this position is not wired to anything yet.</Text>
          ) : (
            <Stack gap={7}>
              {comms.map((cm) => (
                <Box key={cm.counterpartNode + cm.archetype} onClick={() => onSelectNode(cm.counterpartNode)}
                  style={{ padding: "8px 9px", borderRadius: 8, background: "var(--bg-soft)", border: "1px solid var(--border-soft)", cursor: "pointer" }}>
                  <Row gap={7} align="center">
                    <ColorSwatch color={hueColor(cm.hue)} size={7} />
                    <Text as="span" size={12} weight={500}>{cm.archetypeLabel} · {cm.counterpartName}</Text>
                  </Row>
                  <Row gap={5} wrap style={{ marginTop: 6 }}>
                    {cm.sends.map((f) => <FormChip key={"o" + f.id} form={f} />)}
                    {cm.receives.map((f) => <FormChip key={"i" + f.id} form={f} />)}
                  </Row>
                </Box>
              ))}
            </Stack>
          )}
        </Box>

        <AuthoredElsewhere />
      </Box>
    );
  }

  // ── relationship mode ──
  const rel = org.relationships.find((r) => r.id === sel.id);
  if (!rel) return <Box style={PANEL} />;
  const arch = archetypeById(rel.archetype);
  const from = org.positions.find((p) => p.nodeId === rel.from);
  const to = org.positions.find((p) => p.nodeId === rel.to);
  const aLabel = from ? positionDisplay(from, personas).name : rel.from;
  const bLabel = to ? positionDisplay(to, personas).name : rel.to;
  const fwd = (arch?.forward ?? []).map(formById).filter((f): f is NonNullable<typeof f> => !!f);
  const back = (arch?.backward ?? []).map(formById).filter((f): f is NonNullable<typeof f> => !!f);

  return (
    <Box style={PANEL}>
      <Box style={{ ...BLOCK, padding: "16px 17px 15px" }}>
        <BlockLabel right={<Text as="span" mono size={9} tone="dim">{rel.archetype}</Text>}>Relationship</BlockLabel>
        <Row gap={8} align="center">
          <ColorSwatch color={hueColor(arch?.hue ?? 0)} size={8} />
          <Text as="span" weight={600} size={13}>{arch?.label ?? rel.archetype}</Text>
        </Row>
        <Row gap={8} align="center" style={{ marginTop: 12 }}>
          <Text as="span" weight={600} size={12.5} style={{ cursor: "pointer" }} onClick={() => onSelectNode(rel.from)}>{aLabel}</Text>
          <Text as="span" tone="dim">—</Text>
          <Text as="span" size={11} tone="muted">{arch?.label}</Text>
          <Text as="span" tone="dim">→</Text>
          <Text as="span" weight={600} size={12.5} style={{ cursor: "pointer" }} onClick={() => onSelectNode(rel.to)}>{bLabel}</Text>
        </Row>
        {arch && <Text as="p" size={11} tone="muted" style={{ lineHeight: 1.45, margin: "11px 0 0" }}>{arch.blurb}</Text>}
      </Box>

      <Stack gap={10} style={{ padding: "15px 17px 20px" }}>
        <BlockLabel>Communication forms</BlockLabel>
        <FormLane from={aLabel} to={bLabel} forms={fwd} hue={arch?.hue ?? 0} />
        <FormLane from={bLabel} to={aLabel} forms={back} hue={arch?.hue ?? 0} />
      </Stack>

      <AuthoredElsewhere />
    </Box>
  );
}

